import{_ as i,C as a,o as s,c as r,ah as o,E as t}from"./chunks/framework.sPHStHqt.js";const v=JSON.parse('{"title":"Billing & Invoices","description":"","frontmatter":{},"headers":[],"relativePath":"tenants/billing-and-invoices.md","filePath":"tenants/billing-and-invoices.md","lastUpdated":1789630599000}'),l={name:"tenants/billing-and-invoices.md"};function c(u,n,p,d,g,h){const e=a("ImagePopup");return s(),r("div",null,[n[0]||(n[0]=o('<h1 id="billing-invoices" tabindex="-1">Billing &amp; Invoices <a class="header-anchor" href="#billing-invoices" aria-label="Permalink to &quot;Billing &amp; Invoices&quot;">​</a></h1><p><em>This page is for a <strong>tenant</strong> — a business managing its own subscription and invoices.</em></p><p>Everything about what you pay lives under <strong>Subscription</strong> in your workspace: your current plan, the option to change it, and every invoice you&#39;ve been charged.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>Where to find your plan and billing</li><li>How to change or cancel your subscription</li><li>How to view and download your invoices</li></ul></div><h2 id="your-plan" tabindex="-1">Your plan <a class="header-anchor" href="#your-plan" aria-label="Permalink to &quot;Your plan&quot;">​</a></h2><p>Open <strong>Subscription → Plans</strong> in your workspace.</p>',6)),t(e,{src:"/images/billing-and-invoices/tenant-billing.png",alt:"Your current plan and options"}),n[1]||(n[1]=o('<p>Your active plan is marked <strong>Current Plan</strong>, with its price and the <strong>validity</strong> dates of the current cycle — when it started and when it renews. The other plans show what you&#39;d move to.</p><ul><li><strong>Upgrade</strong> — switch to a larger plan for more capacity.</li><li><strong>Downgrade</strong> — switch to a smaller one.</li><li><strong>Cancel Subscription</strong> — stop your subscription. You&#39;ll be asked for a reason to confirm.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Cancelling ends your paid subscription. Your CRM stays reachable until the current cycle you&#39;ve already paid for runs out, after which you&#39;ll need to choose a plan again to keep using it.</p></div><h2 id="your-invoices" tabindex="-1">Your invoices <a class="header-anchor" href="#your-invoices" aria-label="Permalink to &quot;Your invoices&quot;">​</a></h2><p>Open <strong>Subscription → Invoices</strong>.</p>',5)),t(e,{src:"/images/billing-and-invoices/tenant-invoices.png",alt:"Your invoices"}),n[2]||(n[2]=o('<p>Every charge is listed with its <strong>Increment Id</strong> (invoice number), <strong>Amount</strong>, <strong>Payment Method</strong>, <strong>Status</strong> and date. You see only your own invoices — no one else&#39;s.</p><p>The download icon in the <strong>Actions</strong> column saves the invoice as a <strong>PDF</strong>, ready for your own bookkeeping.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>These are the same invoices your platform operator sees on their side. If you&#39;re missing one, they can re-send it to you — just ask.</p></div><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>Compare plans before you change → <a href="/tenants/choosing-a-plan">Choosing a Plan</a></li><li>Understand what your plan&#39;s limits mean → <a href="/tenants/tenant-workspace">The Tenant Workspace</a></li><li>Move your CRM to your own domain → <a href="/tenants/custom-domains">Custom Domains</a></li></ul>',5))])}const _=i(l,[["render",c]]);export{v as __pageData,_ as default};
